    function schedulePlacementAnalysis(label,timing){const revision=++placementAnalysisRevision;clearTimeout(placementAnalysisTimer);placementAnalysisTimer=setTimeout(()=>{if(revision!==placementAnalysisRevision)return;const started=performance.now(),row={label,phase:'analysis',analysisMs:0,totalMs:0,ok:false};try{renderAnalysis();row.analysisMs=Number((performance.now()-started).toFixed(1));row.totalMs=Number((performance.now()-timing.startedAt).toFixed(1));row.ok=true}catch(error){row.analysisMs=Number((performance.now()-started).toFixed(1));row.totalMs=Number((performance.now()-timing.startedAt).toFixed(1));row.error=String(error?.message||error);console.error(`placement:${label} 2차 분석 실패`,error);if(els.goalDirections)els.goalDirections.innerHTML='<p class="goal-analysis-fallback">표시가 저장되었습니다. 일부 확장 분석을 일시적으로 완료할 수 없습니다.</p>'}recordPlacementTiming(row)},0)}
