    function updateCoreProgress(){const depth=placementDataDepth(),optional=depth.dimensions.filter(dimension=>!dimension.covered).slice(0,4);els.coreProgress.textContent=depth.items.length?`${depth.items.length}개 자료 제공 · ${depth.tier}`:'아직 자료가 표시되지 않음';els.planningDepthLabel.textContent=depth.items.length?`${depth.tier} · ${depth.items.length}개 자료 제공`:'아직 표시 안 함 · 꼭 채울 필요 없음';els.planningCovered.innerHTML=depth.covered.length?`<strong>현재 다룬 면</strong><div>${depth.covered.map(dimension=>`<span>${dimension.name}</span>`).join('')}</div>`:'<span class="depth-empty">확실한 위치를 하나 먼저 표시하면 분석을 시작할 수 있습니다.</span>';els.planningOptional.innerHTML=optional.length?`<strong>분석을 더 세밀하게 하려면 선택적으로 보완</strong><div>${optional.map(dimension=>`<span>${dimension.name}</span>`).join('')}</div><small>모두 필수가 아니며, "완성"을 위해 억지로 채울 필요도 없습니다.</small>`:'<small>현재 자료가 이미 많은 면을 다룹니다. 현장 필요에 따라 계속 보완할 수 있지만 억지로 채울 필요는 없습니다.</small>';els.clearLayout.disabled=!depth.items.length;setStepDone(5,depth.items.length>0);setStepDone(6,depth.items.length>0)}
