    function renderPlacements(){if(!lastChart)return;migrateCoarsePlacements();renderPlanningDirections();updateCoreProgress();const cells=[],displayPalaces=planningPalaces(),fineLabels=planningFineLabels();for(let row=0;row<9;row++){for(let col=0;col<9;col++){const displayIndex=Math.floor(row/3)*3+Math.floor(col/3),palace=displayPalaces[displayIndex],palaceIndex=gridPalaces.indexOf(palace),fine=(row%3)*3+(col%3),items=Array.isArray(fineCellsFor(palace)[fine])?fineCellsFor(palace)[fine]:[],active=Boolean(activeItem)&&items.includes(activeItem),preview=activeItem?adviceFor(activeItem,palace,palaceIndex,lastChart):null,status=preview?.status||'一般',shortLabel=labels[palace].split('｜')[0].replace('宮','').replace('궁',''),palaceLabel=fine===0?`<span class="detail-palace">${shortLabel}<small>${activeItem?statusLabel(status):'선택 대기'}</small></span>`:'',tagText=items.length?`<span>${roomLabel(items[0])}</span>${items.length>1?`<span>＋${items.length-1}</span>`:''}`:'<i class="detail-empty" aria-hidden="true"></i>',selection=activeItem?`${roomLabel(activeItem)} ${statusLabel(status)}`:'아직 표시 항목을 선택하지 않음';cells.push(`<button type="button" class="detail-cell preview-${status} ${col===2||col===5?'major-right':''} ${row===2||row===5?'major-bottom':''} ${active?'active':''}" data-palace="${palace}" data-fine="${fine}" data-row="${row}" data-col="${col}" title="${activeItem?`${roomLabel(activeItem)}을(를) ${labels[palace]}에 둠: ${statusLabel(status)}`:'표시할 항목을 하나 먼저 고르세요'}${items.length?', 현재 '+items.map(roomLabel).join('、'):''}" aria-label="${labels[palace]}, ${fineLabels[fine]}, ${selection}, ${items.length?items.map(roomLabel).join('、'):'표시 안 함'}">${palaceLabel}<span class="detail-tags">${tagText}</span></button>`)}}els.placeGrid.innerHTML=cells.join('');els.placeGrid.querySelectorAll('.detail-cell').forEach(btn=>btn.onclick=()=>toggleDetailedCell(btn.dataset.palace,Number(btn.dataset.fine)))}
    function toggleDetailedCell(palace,fine){if(!activeItem){showToast('표시할 항목을 하나 먼저 고르세요',false);renderPlacementTip();return}if(!locked){els.lockPrompt.textContent=`먼저 현재 ${heading.toFixed(1)}°(${lastChart.sitting}산${lastChart.facing}향)를 고정한 뒤 주택 격국을 배치하세요.`;els.lockDialog.showModal();return}const item=activeItem;commitPlacementMutation(`toggle:${item}`,()=>{const map=fineCellsFor(palace),items=Array.isArray(map[fine])?map[fine]:[],wasHere=items.includes(item);map[fine]=wasHere?items.filter(value=>value!==item):[...items,item];finePlacements[palace]=map;if(wasHere){if(!finePositionsFor(palace,item).length)placements[palace]=tagsFor(palace).filter(value=>value!==item)}else ensureInPalace(palace,item);activePalace=palace})}
