    function temporalProfessionalHtml(t){return `<p><strong>${t.annual.effectiveYear}년 ${t.annual.ganzhiYear}년</strong> · 연성 ${t.annual.centerStar} 입중<br><small>${t.annual.startLocal.text} ~ ${t.annual.endLocal.text}</small></p><p><strong>${t.monthly.startSolarTerm}절월</strong> · 월성 ${t.monthly.centerStar} 입중<br><small>${t.monthly.startLocal.text} ~ ${t.monthly.endLocal.text}</small></p><div class="temporal-grid">${temporalGridHtml(t)}</div><p><small>판단 순서: 본명반 ＞ 원운 ＞ 유년 ＞ 유월. 본명운／산／향반은 변하지 않으며, 연·월 객성만 겹쳐 사용합니다. 출처: 《현공집요(玄空輯要)》 연·월 자백 입중표와 《현공고의(玄空古義)》 연월일시 자백도.</small></p>`}
    function temporalHomeHtml(c,a){const t=temporalAssessment(c,a),actions=t.currentActions,annualRows=[...actions.annualAttention,...actions.annualUse].filter((row,index,rows)=>rows.findIndex(item=>item.palace===row.palace)===index).slice(0,4),monthRows=actions.monthlyAttention.slice(0,3),annualItems=(annualRows.length?annualRows:[actions.byPalace[0]]).map(row=>`<li>${safeText(row.annualAction)}</li>`).join(''),monthItems=(monthRows.length?monthRows.map(row=>`<li>${safeText(row.monthlyAction)}</li>`):['<li>이 절기 달에는 추가로 높일 단기 알림이 없습니다.</li>']).join(''),empty=actions.emptyStateAction?`<p class="temporal-empty">${safeText(actions.emptyStateAction)}</p>`:'',professional=temporalProfessionalHtml(t),annualContent=`<ul class="temporal-action-list">${annualItems}</ul>${empty}`,monthContent=`<ul class="temporal-action-list">${monthItems}</ul><p>이것은 단기 알림이며, 다음 절기 이후 다시 계산됩니다.</p>`;return `<section class="temporal-home" data-copy-layer="beginner">${ExplainableInsightCard({eyebrow:'유년 알림',title:'올해 이 집을 어떻게 쓸까',content:annualContent,professionalBody:professional,target:'home-annual-professional',className:'temporal-annual-card'})}${ExplainableInsightCard({eyebrow:'유월 알림',title:`이번 달 특히 주의 · 약 ${temporalDate(t.monthly.endEpochMs)}까지`,supporting:'다음 절기 이후 다시 계산됩니다.',content:monthContent,professionalBody:professional,target:'home-monthly-professional',className:'temporal-monthly-card'})}</section>`}
