    function globalPatterns(c){const pattern=sCore.analyzeCorePattern(c),fanFu=sCore.analyzeFanFuYin(c),items=[],adverse=Boolean(pattern.isShangShan||pattern.isXiaShui||fanFu.mountainFullFuYin||fanFu.facingFullFuYin||fanFu.mountainFullFanYin||fanFu.facingFullFanYin),unreached=!pattern.isWangShan||!pattern.isWangXiang;items.push(pattern.isWangShan?'산성 영성이 좌산에 이름':'산성 영성이 좌산에 이르지 못함');items.push(pattern.isWangXiang?'향성 영성이 향에 이름':'향성 영성이 향수에 이르지 못함');if(pattern.isShangShan)items.push('향상 영성이 산에 이름: 상산(上山)');if(pattern.isXiaShui)items.push('산상 영성이 향에 이름: 하수(下水)');if(pattern.isDoubleAtMountain)items.push('쌍성도산(雙星到山)');if(pattern.isDoubleAtFacing)items.push('쌍성도향(雙星到向)');if(pattern.isWangShan&&pattern.isWangXiang)items.push('도산도향／왕산왕향(旺山旺向)');if(fanFu.mountainFullFuYin)items.push('산성 전반 복음(伏吟)');if(fanFu.facingFullFuYin)items.push('향성 전반 복음(伏吟)');if(fanFu.mountainFullFanYin)items.push('산성 전반 반음(反吟)');if(fanFu.facingFullFanYin)items.push('향성 전반 반음(反吟)');if(c.shan.every((n,i)=>n+c.yun[i]===10))items.push('산성과 운성 전국 합십(合十)');if(c.xiang.every((n,i)=>n+c.yun[i]===10))items.push('향성과 운성 전국 합십(合十)');return {items,atMountain:pattern.isWangShan,atFacing:pattern.isWangXiang,adverse,unreached,pattern,fanFu}}
    function fullRiskText(a){const names=[];if(a.fanFuYin.fullFanYin)names.push('반음(反吟)');if(a.fanFuYin.fullFuYin)names.push('복음(伏吟)');if(names.length)return `중대 반국: ${names.join('／')}`;if(a.fanFuYin.riskLevel==='HIGH')return '핵심 궁: 국부 반／복음 관계 있음';return '반음·복음: 중대 구조 없음'}
