    function sLevelReportHtml(a){const p=a.pattern,e=a.earthLuck,rental=plainDecision(a,'rental'),purchase=plainDecision(a,'purchase'),estimateNote=headingConfidence===onboarding.HEADING_CONFIDENCE.QUICK_ESTIMATE?'<p><strong>측정 상태:</strong>아래 전문 반 이름은 현재 추정 각도로 생성됩니다. 이후 방향을 다시 확인할 수 있습니다.</p>':'',flagText=[p.wangShan?'왕산(旺山)':null,p.wangXiang?'왕향(旺向)':null,p.shangShan?'상산(上山)':null,p.xiaShui?'하수(下水)':null,p.doubleAtMountain?'쌍성도산':null,p.doubleAtFacing?'쌍성도향':null].filter(Boolean).join('、')||'추가 플래그 없음',baseProfessional=`${estimateNote}<section class="professional-section"><h4>원국 격국</h4><p><strong>${p.copy.label}</strong>｜${p.copy.summary}${a.originalPeriodActive?`현재도 성립 당시의 ${a.housePeriod}운입니다.`:`이는 ${a.housePeriod}운에 성립한 원국이며, 현재는 ${a.currentPeriod}운에 들어섰습니다.`}</p><div class="s-core-metrics"><div><small>반세 플래그</small><b>${flagText}</b></div><div><small>반음／복음</small><b>${fullRiskText(a)}</b></div><div><small>지운／입수</small><b>${e.theoreticalEarthLuckYears}년 · ${imprisonmentText(a)}</b></div></div></section><section class="professional-section"><h4>용어와 판단</h4><div class="copy-explanations">${glossaryExplanationHtml(a)}</div></section>`,rentalProfessional=`${baseProfessional}<section class="professional-section"><h4>전월세 판독</h4><p>${a.rentalAssessment.label}｜${a.rentalAssessment.reasons.join('；')}.</p></section>`,purchaseProfessional=`${baseProfessional}<section class="professional-section"><h4>매매 판독</h4><p>${a.purchaseAssessment.label}｜${a.purchaseAssessment.reasons.join('；')}.</p></section>`;return `<section class="s-level-report"><div class="s-decision-grid">${ExplainableInsightCard({eyebrow:'전월세라면',title:rental[0],supporting:rental[1],professionalBody:rentalProfessional,className:`s-decision ${decisionClass(a.rentalAssessment.code)}`})}${ExplainableInsightCard({eyebrow:'매매라면',title:purchase[0],supporting:purchase[1],professionalBody:purchaseProfessional,className:`s-decision ${decisionClass(a.purchaseAssessment.code)}`})}</div></section>`}
    function sDebugHtml(a){const p=a.pattern,f=a.fanFuYin,i=a.imprisonment,e=i.standard,locals=[...f.localFuYinDetails,...f.localFanYinDetails],localHtml=locals.length?locals.map(row=>`<div class="audit-item ${row.severity==='CORE'?'warn':''}"><b>${row.palace}</b><span>${row.type} · ${row.leftValue}/${row.rightValue} · ${row.scope} · ${row.severity}</span></div>`).join(''):'<div class="audit-item"><b>—</b><span>LOCAL 관계 없음</span></div>';return `<section class="analysis-block wide professional-only"><h3>전문 계산 추적</h3><div class="chips"><span class="chip">housePeriod ${a.housePeriod}</span><span class="chip">currentPeriod ${a.currentPeriod}</span><span class="chip ${a.originalPeriodActive?'':'warn'}">originalPeriodActive ${a.originalPeriodActive}</span><span class="chip">rulingStar ${a.rulingStar}</span><span class="chip">${a.calculationMethod==='replacement'?'겸향 체괘':'정향 하괘'}</span></div><p><strong>좌궁 ${a.sitting.palace}:</strong> 산성 ${a.sitting.mountainStar}、향성 ${a.sitting.facingStar}<br><strong>향궁 ${a.facing.palace}:</strong> 산성 ${a.facing.mountainStar}、향성 ${a.facing.facingStar}</p><div class="audit-list">${[['왕산',p.wangShan],['왕향',p.wangXiang],['상산',p.shangShan],['하수',p.xiaShui],['쌍성도산',p.doubleAtMountain],['쌍성도향',p.doubleAtFacing]].map(([name,value])=>`<div class="audit-item ${value?'':'warn'}"><b>${value?'✓':'—'}</b><span>${name} = ${value}</span></div>`).join('')}</div><p><strong>반·복음 FULL:</strong> 산복 ${f.mountainFullFuYin}、향복 ${f.facingFullFuYin}、산반 ${f.mountainFullFanYin}、향반 ${f.facingFullFanYin}; 범위 ${f.scope}, 위험 ${f.riskLevel}.</p><div class="audit-list">${localHtml}</div><p><strong>imprisonment.standard:</strong> 부모 운반 향궁 ${e.facingParentStar} → ${e.imprisonmentPeriod}운／${e.imprisonmentStartYear}년; 소삼원 ${e.theoreticalEarthLuckYears}년, 검증 ${e.oracleMatches}.<br><strong>imprisonment.qiXing:</strong> 산중 ${i.qiXing.mountainCenterStar}、향중 ${i.qiXing.facingCenterStar}; 산수 ${i.qiXing.mountainStarImprisonedNow}、향수 ${i.qiXing.facingStarImprisonedNow}.<br><strong>imprisonment.special:</strong> 적용 ${i.special.applicable}、${i.special.type}${i.special.applicable?`、${i.special.imprisonmentPeriod}운／${i.special.imprisonmentStartYear}년`:''}.<br><strong>imprisonment.effective:</strong> ${i.effective.sourceLayer}／${i.effective.imprisonmentType}／${i.effective.status}.</p><p class="source-ref">${a.sources.CORE_PATTERN.level}: ${a.sources.CORE_PATTERN.title}<br>${a.sources.FAN_FU_YIN.level}: ${a.sources.FAN_FU_YIN.title}<br>${a.sources.EARTH_LUCK.level}: ${a.sources.EARTH_LUCK.title}<br>${a.sources.SEVEN_STAR_IMPRISONMENT.level}: ${a.sources.SEVEN_STAR_IMPRISONMENT.title}</p></section>`}
    function dataQuality(){const all=Object.values(placements).flat(),hasDoor=all.some(x=>x==='大門'||x==='次要門'),hasRoom=all.some(x=>x.includes('臥室')||x.includes('房')||x==='客廳'||x==='工作室'),hasService=all.some(x=>x==='廚房'||x==='爐灶'||x==='廁所'||x==='浴室'),hasOpen=all.some(x=>['窗戶','陽台','道路','動水','道路／動水','空曠處','低處','空曠／低處','高樓','實山','高樓／實山'].includes(x)),hasBasis=periodBasis!=='trial',stats=readingStats(),hasReading=readings.length===1;return {all,hasDoor,hasRoom,hasService,hasOpen,hasBasis,hasReading,readingStats:stats,score:5+(locked?15:0)+(hasBasis?15:0)+(hasReading?10:0)+(hasDoor?20:0)+(hasRoom?15:0)+(hasService?10:0)+(hasOpen?10:0)}}
    function palaceSentence(palace,i,c){const s=c.shan[i],x=c.xiang[i],tags=tagsFor(palace),hasYin=tags.some(t=>yinItems.has(t)),hasYang=tags.some(t=>yangItems.has(t)),bits=[];if(hasYin)bits.push(`정적 용도는 먼저 산성 ${s}(${starMeta[s].element})을 읽고, 높고 실한 承托이 있는지 살핍니다`);if(hasYang)bits.push(`문·창·발코니·동선은 먼저 향성 ${x}(${starMeta[x].element})을 읽고, 실제로 동기와 개방이 있는지 살핍니다`);if(!tags.length)bits.push(`육사(六事)가 표시되지 않아 산 ${s}、향 ${x}의 반면 자료만 보존할 수 있습니다`);bits.push(`산·향 두 성은 "${relation(starMeta[s].element,starMeta[x].element)}" 관계입니다. 환경 영향을 더하려면 3단계에서 높은 건물·도로·개활지를 표시하세요`);if(s===c.p||x===c.p)bits.push(`${c.p}은(는) 당운 영성입니다. 이 궁에 영성이 있으나, 쓸 수 있는지는 성층과 실제 공실·동정에 달려 있습니다`);return bits.join('. ')+'.'}
    function itemSentence(item,palace,i,c){const base=profileAliases[item]||item,s=c.shan[i],x=c.xiang[i],atSitting=palace===c.sPalace,atFacing=palace===c.fPalace,L=roomLabel(item);if(base==='大門'||base==='次要門')return `${L}은(는) 향성 ${x}을(를) 첫 층으로 봅니다. ${x===c.p?'당운 영성이 여기 있어, 문이 실제로 자주 쓰이고 외부 진입로가 기를 보낼 때 비로소 쓸 수 있는 후보입니다':'당운 영성이 이 문 궁에 없으므로 동궁 성조·진입로·사용 빈도를 봐야 하며, 문 이름만으로 길흉을 정할 수 없습니다'}.`;if(base==='窗戶'||base==='陽台'||base==='道路／動水'||base==='空曠／低處')return `${L}은(는) 낮고·비고·움직이는 承接 자료에 속해 먼저 향성 ${x}을(를) 확인합니다. ${x===c.p?'당운 향성을 받을 수 있으나, 방향·개방 정도·실제 흐름을 확인해야 합니다':'물이나 개구부가 있다고 바로 왕으로 보지 말고, 실제로 어느 향성을 발동시키는지 봐야 합니다'}.`;if(base==='主臥室'||base==='次臥室'||base==='書房'||base==='神位')return `${L}은(는) 오래 머물거나 비교적 정적인 사용에 속해 먼저 산성 ${s}을(를) 확인합니다. ${s===c.p?'당운 산성이 여기 있어, 공간이 조용하고 높고 실하며 실제로 쓰일 때 承托 조건을 갖춥니다':'산성 영성이 여기 없으므로 왕쇠·동궁 향성·방문·사용자를 함께 보며, 당장 사람 일에 대한 단언은 하지 않습니다'}.`;if(base==='高樓／實山')return `${L}은(는) 높고 실한 承托 자료로 먼저 산성 ${s}과(와) 맞춰 봅니다. ${s===c.p?'영성이 산에 이르는 형세 증거 후보가 될 수 있습니다':'낮고 비고 움직이는 기가 필요한 향성 위치를 누르고 있는지 먼저 확인합니다'}${atFacing?'. 또 향수에 있으므로 조만(朝滿)·납기 차단을 특히 확인해야 합니다':''}.`;if(base==='廚房'||base==='爐灶')return `${L}은(는) 불과 잦은 조작을 동반하므로 먼저 산 ${s}、향 ${x} 및 오행 관계를 기록하고, 통풍·열원·전선·소방을 확인합니다. 반면은 안전 점검을 대체하지 않습니다.`;if(base==='廁所')return `${L}은(는) 먼저 습기·통풍·누수·사용 빈도를 기록한 뒤 산 ${s}、향 ${x}을(를) 교재 취상 자료로 삼습니다. 성수로 바로 질병을 추론할 수 없습니다.`;if(base==='魚缸／水景')return `${L}은(는) 눈에 보이는 동수 조건을 늘리므로, 먼저 향성 ${x}이(가) 여기서 발동되기에 적합한지 확인하고 누수·하중·관리를 점검합니다. "물이 있으면 재물 왕"이 아닙니다.`;if(base==='樓梯'||base==='電梯'||base==='走道／通道'||base==='空調／風口')return `${L}은(는) 반복 흐름이나 송기를 뜻해 향성 ${x}을(를) 더 쉽게 쓰이게 할 수 있습니다. 동선 방향·빈도와 실제로 대문에 연결되는지 기록해야 합니다.`;if(base==='客廳'||base==='餐廳')return `${L}은(는) 머묾과 활동을 겸하므로 산성 ${s}、향성 ${x}을(를) 모두 읽고, 주 출입구·좌석·창·발코니로 어느 층이 더 자주 발동되는지 판단합니다.`;if(base==='儲藏室')return `${L}은(는) 비교적 정적이고 적게 쓰므로 먼저 산성 ${s}을(를) 읽되, 그 발동 강도를 안방이나 상용 문과 같게 볼 수 없습니다.`;return `${L}은(는) 위치가 정해졌습니다. 실제 사용 빈도·공실 높낮이·문로 연결을 보완해 주세요.`}
    function renderCapabilities(){els.capabilityGrid.innerHTML=pro.capabilities.map(([title,copy],i)=>`<article class="capability-item"><strong>${String(i+1).padStart(2,'0')} · ${title}</strong><p>${copy}</p></article>`).join('')}
